// Shared domain types that are not generated by Prisma.
//
// Database row shapes come from `lib/generated/prisma/client`; what lives here is the
// plaintext side of the sealed fields (which only ever exists inside a browser) and the
// error envelope the API returns.

export type RealmRole =
  | "tide-realm-admin"
  | "custodian"
  | "custodian-women"
  | "proponent"
  | "minister"
  | `permit-${string}`;

export interface AppUser {
  id: string; // token `sub`
  username: string;
  name: string;
  roles: string[];
}

/**
 * The plaintext of a place's sealed fields. Assembled in a custodian's browser before
 * sealing, and reassembled there after opening. No server-side code constructs this from
 * stored data, because no server-side code can read it.
 */
export interface SiteDetails {
  name: string;
  description: string;
  significance: string;
  boundary: [number, number][]; // polygon in zone-grid units, never coordinates
  recordedBy: string;
  recordedOn: string; // ISO date
}

export interface RestrictedLayer {
  audience: "women";
  knowledge: string;
  protocol: string;
}

export interface ApiError {
  error: { code: string; message: string };
}
